const CACHE='codequest-v1.0.0';
const FILES=["./", "./index.html", "./manifest.json", "./js/utils.js", "./js/app.js", "./js/question-loader.js", "./js/router.js", "./js/storage.js", "./js/theme.js", "./js/code-renderer.js", "./js/quiz-engine.js", "./js/database.js", "./js/question-validator.js", "./js/search.js", "./data/php.js", "./data/python.js", "./data/kotlin.js", "./data/c.js", "./data/java.js", "./data/data-structures.js", "./data/swift.js", "./data/web.js", "./data/typescript.js", "./data/ruby.js", "./data/cpp.js", "./data/algorithms.js", "./data/css.js", "./data/go.js", "./data/sql.js", "./data/dart.js", "./data/cs.js", "./data/html.js", "./data/developer.js", "./data/javascript.js", "./data/rust.js", "./data/csharp.js", "./data/android.js", "./data/catalog.js", "./css/variables.css", "./css/app.css", "./assets/icons/icon-192.png", "./assets/icons/icon-512.png", "./assets/icons/logo.svg"];
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(FILES);await self.skipWaiting()})())});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('codequest-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();for(const c of await self.clients.matchAll())c.postMessage({type:'offline-ready'})})())});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith((async()=>{const cache=await caches.open(CACHE);const cached=await cache.match(event.request,{ignoreSearch:true});if(cached)return cached;try{return await fetch(event.request)}catch(error){if(event.request.mode==='navigate')return (await cache.match('./index.html'));throw error}})())});
